// Alerts only on the live -> not-live TRANSITION. A steady 'not live' is normal most of
// the day, so alerting on the state itself would be constant noise and get muted.
//
// Signal source: /api/stream/youtube-status computes `live` via isHlsLive(), the same check
// the public /live page uses -- including MediaMTX's cookie/redirect dance and the GET-not-HEAD
// requirement. If this says not live, the page shows nothing. That is the thing we care about.

const store = $getWorkflowStaticData('global');
const res = $input.first().json;
const status = res.statusCode || 0;
const reachable = status >= 200 && status < 400;

// A network blip reaching our own API is not evidence the stream dropped. Skip the round
// entirely and keep the previous state, otherwise every hiccup pages us mid-show.
if (!reachable) {
  return [];
}

let live = false;
try {
  const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  live = body && body.live === true;
} catch (err) {
  return [];
}

const wasLive = store.wasLive === true;
store.wasLive = live;

// Stream just came up — remember when, so the drop alert can say how long it ran.
if (live && !wasLive) {
  store.liveSince = new Date().toISOString();
  return [];
}

if (!live && wasLive) {
  const since = store.liveSince ? new Date(store.liveSince) : null;
  const mins = since ? Math.round((Date.now() - since.getTime()) / 60000) : null;
  store.liveSince = null;

  const lines = [
    'The livestream is no longer publishing.',
    '',
    mins !== null ? `It had been live for about ${mins} minute(s).` : '',
    '',
    'If the show is still running, OBS has disconnected or MediaMTX stopped ingesting.',
    'Page:    https://www.stpetemusic.live/live',
    'Checked: https://www.stpetemusic.live/api/stream/youtube-status',
    `Time:    ${new Date().toISOString()}`,
  ];

  return [{ json: { subject: '[StPeteMusic] ALERT: stream STOPPED', text: lines.join('\n') } }];
}

return [];
